// Time series for the dashboard. Until a PLC gateway writes readings to ras_tag_readings, every attribute is
// generated by a deterministic model of the hatchery (daily and seasonal cycles, embryo oxygen uptake over the
// incubation cycle, and occasional upsets), so the same moment always gives the same value at every zoom level.
export type Range = 'live' | 'hour' | 'day' | 'week' | 'month' | 'year'
export type Ctx = { li: number; pos: number }
export type Pt = { t: number; v: number; lo: number; hi: number; label: string; partial?: boolean }

const H = (i: number, s: number) => { const x = Math.sin(i * 127.1 + s * 311.7) * 43758.5453; return x - Math.floor(x) }
const vn = (x: number, s: number) => { const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f); return H(i, s) * (1 - u) + H(i + 1, s) * u }
const ev = (t: number, s: number, period: number, prob: number, width: number) => {
  let a = 0
  const k0 = Math.floor(t / period)
  for (let k = k0 - 1; k <= k0; k++) if (H(k, s) < prob) { const c = (k + 0.15 + 0.7 * H(k, s + 7)) * period, z = (t - c) / width; a = Math.max(a, Math.exp(-z * z)) }
  return a
}
const seed = (id: string) => { let h = 7; for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) % 9973; return h }
const HR = 3600000, DAY = 86400000
const tz = -new Date().getTimezoneOffset() / 60
const diurnal = (t: number) => Math.sin(((((t / HR + tz) % 24) - 14) / 24) * 2 * Math.PI)
const season = (t: number) => Math.sin((((t / DAY + tz / 24) % 365.25) - 45) / 365.25 * 2 * Math.PI)

const temp = (t: number) => 29 + 0.7 * diurnal(t) + 1.2 * season(t) + 0.15 * vn(t / 6e5, 1) + 3.6 * ev(t, 11, 7 * DAY, 0.3, 4 * HR)
const sumpDO = (t: number) => 7.6 - 0.35 * diurnal(t) - 0.3 * season(t) + 0.12 * vn(t / 9e5, 2) - 2.9 * ev(t, 12, 9 * DAY, 0.28, 5 * HR)
const lineTemp = (t: number, c: Ctx) => temp(t) + 0.05 * (c.li - 2.5) + 0.04 * vn(t / 4e5, 20 + c.li)
const lineFlow = (t: number, c: Ctx) => 77 + 0.9 * (vn(t / 3e5, 30 + c.li) - 0.5) * 2 - 6 * ev(t, 31 + c.li, 12 * DAY, 0.2, 3 * HR)
const jarBlock = (t: number, c: Ctx) => ev(t, 40 + c.li * 20 + c.pos, 6 * DAY, 0.05, 2.5 * HR)
const jarFlow = (t: number, c: Ctx) => 4.28 * (1 + 0.025 * (vn(t / 2e5, 50 + c.pos + c.li * 20) - 0.5) * 2) * (1 - 0.92 * jarBlock(t, c))
// Egg oxygen uptake rises through a 72 h incubation (stage 1 to 4), then the jar is reloaded.
const uptake = (t: number, c: Ctx) => { const ph = ((t / HR + c.pos * 3.7 + c.li * 11) % 72) / 72; return 1200 * 0.12 * (1 + 1.2 * ph) / 60 }
const jarDO = (t: number, c: Ctx) => { const q = jarFlow(t, c), din = sumpDO(t) - 0.2; return q > 0.05 ? Math.max(0, din - uptake(t, c) / q) : 0 }

export type Attr = {
  id: string; label: string; unit: string; dec: number; scope: 'ras' | 'pump' | 'line' | 'jar'; lim?: string; fn: (t: number, c: Ctx) => number
}
export const ATTRS: Attr[] = [
  { id: 'nh3', label: 'Ammonia', unit: 'mg/L', dec: 2, scope: 'ras', lim: 'nh3', fn: t => 0.13 + 0.04 * (1 + diurnal(t)) / 2 + 0.015 * vn(t / 7e5, 3) + 0.2 * ev(t, 13, 7 * DAY, 0.3, 5 * HR) },
  { id: 'no2', label: 'Nitrite', unit: 'mg/L', dec: 2, scope: 'ras', lim: 'no2', fn: t => 0.07 * ev(t, 14, 11 * DAY, 0.3, 5 * HR) },
  { id: 'no3', label: 'Nitrate', unit: 'mg/L', dec: 1, scope: 'ras', lim: 'no3', fn: t => 5 * ev(t, 15, 13 * DAY, 0.3, 8 * HR) },
  { id: 'ph', label: 'pH', unit: '', dec: 2, scope: 'ras', lim: 'ph', fn: t => 7.4 + 0.12 * diurnal(t) + 0.05 * (vn(t / 8e5, 4) - 0.5) - 0.7 * ev(t, 16, 10 * DAY, 0.3, 6 * HR) },
  { id: 'alk', label: 'Alkalinity', unit: 'mg/L', dec: 0, scope: 'ras', lim: 'alk', fn: t => 78 + 6 * season(t) + 4 * vn(t / 1.2e6, 5) + 28 * ev(t, 17, 14 * DAY, 0.3, 9 * HR) },
  { id: 'turb', label: 'Turbidity', unit: 'NTU', dec: 1, scope: 'ras', lim: 'turb', fn: t => 6 + 1.5 * (1 + diurnal(t)) + 2.5 * vn(t / 5e5, 6) + 11 * ev(t, 18, 6 * DAY, 0.3, 4 * HR) },
  { id: 'cah', label: 'Calcium hardness', unit: 'mg/L', dec: 0, scope: 'ras', lim: 'cah', fn: t => 120 + 8 * season(t) + 14 * vn(t / 3e6, 7) + 80 * ev(t, 19, 21 * DAY, 0.3, 12 * HR) },
  { id: 'hard', label: 'Total hardness', unit: 'mg/L CaCO3', dec: 0, scope: 'ras', lim: 'hard', fn: t => 150 + 8 * season(t) + 16 * vn(t / 3e6, 8) },
  { id: 'pdis', label: 'Pump discharge pressure', unit: 'bar', dec: 2, scope: 'pump', fn: t => 0.27 + 0.008 * (vn(t / 2e5, 9) - 0.5) * 2 },
  { id: 'ptot', label: 'Total supply flow', unit: 'L/min', dec: 0, scope: 'pump', fn: t => [0, 1, 2, 3, 4, 5].reduce((a, li) => a + lineFlow(t, { li, pos: 0 }), 0) },
  { id: 'pspd', label: 'Pump speed', unit: '%', dec: 0, scope: 'pump', fn: t => 100 - 8 * vn(t / 4e6, 10) * (H(Math.floor(t / (3 * DAY)), 3) < 0.15 ? 1 : 0) },
  { id: 'sdo', label: 'Sump dissolved oxygen', unit: 'mg/L', dec: 1, scope: 'pump', lim: 'jdo', fn: sumpDO },
  { id: 'stmp', label: 'Sump temperature', unit: '°C', dec: 1, scope: 'pump', lim: 'temp', fn: temp },
  { id: 'lflow', label: 'Line flow', unit: 'L/min', dec: 1, scope: 'line', fn: lineFlow },
  { id: 'ltmp', label: 'Line temperature', unit: '°C', dec: 1, scope: 'line', lim: 'temp', fn: lineTemp },
  { id: 'lprs', label: 'Line header pressure', unit: 'bar', dec: 2, scope: 'line', lim: 'jp', fn: (t, c) => 0.2 - 0.002 * c.li + 0.004 * (vn(t / 2e5, 60 + c.li) - 0.5) },
  { id: 'ldin', label: 'Inlet oxygen', unit: 'mg/L', dec: 1, scope: 'line', fn: t => sumpDO(t) - 0.2 },
  { id: 'ldout', label: 'Overflow oxygen', unit: 'mg/L', dec: 1, scope: 'line', lim: 'jdo', fn: (t, c) => sumpDO(t) - 0.2 - uptake(t, { li: c.li, pos: 9 }) / 4.28 },
  { id: 'lvalve', label: 'Mean valve position', unit: '%', dec: 0, scope: 'line', fn: (t, c) => 40 + 2 * (vn(t / 8e6, 70 + c.li) - 0.5) },
  { id: 'jflow', label: 'Jar flow', unit: 'L/min', dec: 2, scope: 'jar', lim: 'jflow', fn: jarFlow },
  { id: 'jdo', label: 'Jar oxygen out', unit: 'mg/L', dec: 1, scope: 'jar', lim: 'jdo', fn: jarDO },
  { id: 'jprs', label: 'Jar water pressure', unit: 'bar', dec: 2, scope: 'jar', lim: 'jp', fn: (t, c) => 0.2 - 0.0005 * c.pos + 0.003 * (vn(t / 2e5, 80 + c.pos) - 0.5) },
  { id: 'jtmp', label: 'Jar temperature', unit: '°C', dec: 1, scope: 'jar', lim: 'temp', fn: (t, c) => lineTemp(t, c) + 0.04 * Math.sin(c.pos * 1.7) },
]

export const RANGES: { k: Range; label: string; title: string }[] = [
  { k: 'live', label: 'Live', title: 'Last 10 minutes' }, { k: 'hour', label: 'Hourly', title: 'Last 24 hours, one point per hour' },
  { k: 'day', label: 'Daily', title: 'Last 30 days, one point per day' }, { k: 'week', label: 'Weekly', title: 'Last 26 ISO weeks (Monday to Sunday)' },
  { k: 'month', label: 'Monthly', title: 'Last 12 months' }, { k: 'year', label: 'Yearly', title: 'Last 5 years' },
]

export function isoWeek(d: Date): [number, number] {
  const x = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()))
  x.setUTCDate(x.getUTCDate() + 4 - (x.getUTCDay() || 7))
  const y = x.getUTCFullYear()
  return [y, Math.ceil(((+x - +new Date(Date.UTC(y, 0, 1))) / DAY + 1) / 7)]
}
const p2 = (n: number) => String(n).padStart(2, '0')
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

// Bucket boundaries (local time) for each range. The last bucket runs up to now.
export function buckets(range: Exclude<Range, 'live'>, now: number) {
  const n = new Date(now), out: { start: number; end: number; label: string; n: number }[] = []
  const N = { hour: 24, day: 30, week: 26, month: 12, year: 5 }[range], S = { hour: 12, day: 24, week: 28, month: 30, year: 60 }[range]
  const startOf = (i: number) => {
    const d = new Date(now)
    if (range === 'hour') { d.setMinutes(0, 0, 0); d.setHours(d.getHours() - i) }
    else if (range === 'day') { d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - i) }
    else if (range === 'week') { d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - ((d.getDay() + 6) % 7) - 7 * i) }
    else if (range === 'month') return new Date(n.getFullYear(), n.getMonth() - i, 1)
    else return new Date(n.getFullYear() - i, 0, 1)
    return d
  }
  for (let i = N - 1; i >= 0; i--) {
    const a = startOf(i), b = i === 0 ? new Date(now) : startOf(i - 1)
    const label = range === 'hour' ? `${p2(a.getHours())}:00` : range === 'day' ? `${a.getDate()} ${MON[a.getMonth()]}` : range === 'week' ? `W${p2(isoWeek(a)[1])}`
      : range === 'month' ? `${MON[a.getMonth()]} ${String(a.getFullYear()).slice(2)}` : String(a.getFullYear())
    out.push({ start: +a, end: +b, label, n: S })
  }
  return out
}

export function series(a: Attr, range: Range, now: number, c: Ctx): Pt[] {
  if (range === 'live') {
    const pts: Pt[] = []
    for (let i = 120; i >= 0; i--) {
      const t = now - i * 5000, v = a.fn(t, c), d = new Date(t)
      pts.push({ t, v, lo: v, hi: v, label: `${p2(d.getHours())}:${p2(d.getMinutes())}:${p2(d.getSeconds())}` })
    }
    return pts
  }
  return buckets(range, now).map((b, i, all) => {
    let s = 0, lo = Infinity, hi = -Infinity
    for (let j = 0; j < b.n; j++) { const v = a.fn(b.start + ((j + 0.5) / b.n) * (b.end - b.start), c); s += v; lo = Math.min(lo, v); hi = Math.max(hi, v) }
    return { t: (b.start + b.end) / 2, v: s / b.n, lo, hi, label: b.label, partial: i === all.length - 1 }
  })
}
